import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const localeDir = path.join(__dirname, '..', 'locale')

function unescapePo(s) {
  return s
    .replace(/\\n/g, '\n')
    .replace(/\\t/g, '\t')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\')
}

function poEscape(s) {
  return String(s)
    .replace(/\r/g, '')
    .replace(/\\n/g, '\u0000')
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\u0000/g, '\\n')
}

function escRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function parsePo(filePath) {
  const text = fs.readFileSync(filePath, 'utf8')
  const map = new Map()
  let msgid = null
  let msgstr = null
  let collecting = null
  const flush = () => {
    if (msgid !== null && msgstr !== null && msgid !== '') map.set(msgid, msgstr)
    msgid = null
    msgstr = null
    collecting = null
  }
  for (const line of text.split(/\r?\n/)) {
    const idMatch = line.match(/^msgid\s+"(.*)"\s*$/)
    if (idMatch) {
      if (msgid !== null && msgstr !== null) flush()
      collecting = 'id'
      msgid = unescapePo(idMatch[1])
      msgstr = null
      continue
    }
    const strMatch = line.match(/^msgstr\s+"(.*)"\s*$/)
    if (strMatch) {
      collecting = 'str'
      msgstr = unescapePo(strMatch[1])
      continue
    }
    const cont = line.match(/^"(.*)"\s*$/)
    if (cont && collecting) {
      const piece = unescapePo(cont[1])
      if (collecting === 'id') msgid = (msgid || '') + piece
      else msgstr = (msgstr || '') + piece
      continue
    }
    if (!line.trim()) flush()
  }
  flush()
  return map
}

function hasKey(txt, key) {
  return new RegExp(`^msgid\\s+"${escRe(key)}"\\s*$`, 'm').test(txt)
}

/** 删除指定 msgid 的整块（含紧前注释） */
function removeKeyBlock(txt, key) {
  const re = new RegExp(
    `(?:^#.*\\n)*^msgid\\s+"${escRe(key)}"\\s*\\nmsgstr\\s+"(?:\\\\.|[^"\\\\])*"\\s*\\n(?:^"(?:\\\\.|[^"\\\\])*"\\s*\\n)*`,
    'm',
  )
  return txt.replace(re, '')
}

function setOrAppendKey(txt, key, val) {
  const block = `msgid "${key}"\nmsgstr "${poEscape(val)}"\n`
  const re = new RegExp(
    `^msgid\\s+"${escRe(key)}"\\s*\\nmsgstr\\s+"(?:\\\\.|[^"\\\\])*"\\s*\\n(?:^"(?:\\\\.|[^"\\\\])*"\\s*\\n)*`,
    'm',
  )
  if (re.test(txt)) return txt.replace(re, block)
  if (!txt.endsWith('\n')) txt += '\n'
  return txt + '\n' + block
}

