Object.assign(T, ICON_KEYS)

function tr(key, locale, enMap) {
  const bag = T[key]
  if (bag && bag[locale]) return bag[locale]
  if (locale === 'en-GB' && EN_GB_EXTRA[key]) return EN_GB_EXTRA[key]
  if (bag && bag['en-US']) return bag['en-US']
  return enMap.get(key) || ''
}

const enMap = parsePo(path.join(localeDir, 'en-US.po'))
const files = fs.readdirSync(localeDir).filter((f) => f.endsWith('.po')).sort()

let added = 0
let updated = 0
let migrated = 0

for (const file of files) {
  const locale = file.replace(/\.po$/, '')
  const full = path.join(localeDir, file)
  let txt = fs.readFileSync(full, 'utf8')
  const before = txt

  // 1) 迁移旧 allowEdit* → allowViewEdit*
  if (hasKey(txt, 'settings.allowEditAllFiles') || hasKey(txt, 'settings.allowEditAllFilesHint')) {
    txt = removeKeyBlock(txt, 'settings.allowEditAllFiles')
    txt = removeKeyBlock(txt, 'settings.allowEditAllFilesHint')
    migrated++
  }
  // 确保新 key 存在且文案正确（覆盖旧文案）
  for (const k of ['settings.allowViewEditAllFiles', 'settings.allowViewEditAllFilesHint', 'settings.editableExtensionsHint']) {
    const val = tr(k, locale, enMap)
    if (!val) continue
    const prevHas = hasKey(txt, k)
    txt = setOrAppendKey(txt, k, val)
    if (prevHas) updated++
    else added++
  }

  // 2) 补齐相对 en-US 缺失的 key（用当前 txt 解析）
  const tmp = path.join(localeDir, `.__tmp_${locale}.po`)
  fs.writeFileSync(tmp, txt, 'utf8')
  const cur = parsePo(tmp)
  fs.unlinkSync(tmp)

  for (const key of enMap.keys()) {
    if (!key) continue
    if (cur.has(key) && cur.get(key)) continue
    const val = tr(key, locale, enMap)
    if (!val) continue
    txt = setOrAppendKey(txt, key, val)
    added++
    cur.set(key, val)
  }

  if (txt !== before) {
    if (!txt.endsWith('\n')) txt += '\n'
    fs.writeFileSync(full, txt, 'utf8')
    console.log(`[ok] ${file}`)
  } else {
    console.log(`[skip] ${file}`)
  }
}

console.log(`\n[i18n] migrated=${migrated} added≈${added} updated≈${updated}`)
